/* Steam DNA — midnight library blue, glowing store shelves */
.theme-steam-dna {
  --bg: oklch(0.218 0.015 266.9);
  --surface: oklch(0.273 0.035 254.1);
  --surface-2: oklch(0.363 0.054 255.1);
  --fg: oklch(0.899 0.003 228.8);
  --fg-muted: oklch(0.675 0.016 244.8);
  --accent: oklch(0.660 0.114 236.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.794 0.195 123.7);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Work Sans", sans-serif;
  --font-body: "Work Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-steam-dna h1,
.theme-steam-dna h2,
.theme-steam-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-steam-dna h1 { background: linear-gradient(95deg, var(--accent), var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-steam-dna button { background-image: linear-gradient(90deg, #47bfff22, #1a44c222); }

/* depth */
.theme-steam-dna { background-image: linear-gradient(180deg, oklch(0.273 0.035 254.1 / 60%), transparent 320px); }
.theme-steam-dna h2 { padding-bottom: 0.35rem; background: linear-gradient(90deg, var(--accent), transparent 65%) bottom left / 100% 2px no-repeat; }
.theme-steam-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--fg-muted); border-bottom: 1px solid color-mix(in oklab, var(--accent) 40%, transparent); }
.theme-steam-dna tbody td { border-bottom: 1px solid oklch(1 0 0 / 8%); }
.theme-steam-dna tbody tr:hover td { background: linear-gradient(90deg, color-mix(in oklab, var(--accent) 14%, transparent), transparent); }
.theme-steam-dna a { color: var(--accent); text-decoration: none; }
.theme-steam-dna a:hover { color: oklch(0.930 0.040 230.0); text-decoration: underline; text-underline-offset: 3px; }
.theme-steam-dna ::selection { background: var(--accent); color: oklch(0.160 0.02 266); }
.theme-steam-dna input, .theme-steam-dna select, .theme-steam-dna textarea { background: oklch(0.180 0.015 266.9); box-shadow: inset 0 1px 3px oklch(0 0 0 / 45%); }
.theme-steam-dna input:focus-visible, .theme-steam-dna select:focus-visible, .theme-steam-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: inset 0 1px 3px oklch(0 0 0 / 45%), 0 0 10px color-mix(in oklab, var(--accent) 45%, transparent); }
.theme-steam-dna button:hover { background-image: linear-gradient(90deg, #47bfff3a, #a4d0073a); }
.theme-steam-dna kbd { font-family: var(--font-mono); font-size: 0.78em; padding: 0.12em 0.5em; border-radius: var(--radius-sm); background: oklch(0.170 0.012 266.9); border: 1px solid oklch(1 0 0 / 18%); box-shadow: inset 0 -2px 0 oklch(0 0 0 / 50%); }
.theme-steam-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-steam-dna ::-webkit-scrollbar-track { background: oklch(0.180 0.012 266.9); }
.theme-steam-dna ::-webkit-scrollbar-thumb { background: oklch(0.420 0.040 255.0); border-radius: 2px; }
.theme-steam-dna ::-webkit-scrollbar-thumb:hover { background: color-mix(in oklab, var(--accent) 50%, oklch(0.420 0.040 255.0)); }
.theme-steam-dna .label-caps { color: var(--accent-2); letter-spacing: 0.1em; }
.theme-steam-dna .themed-border { border-color: color-mix(in oklab, var(--accent) 35%, var(--line)); }

/* alt mode: community daylight — pale library blue, ink-blue links, deep lime */
.theme-steam-dna.alt-mode {
  --bg: oklch(0.955 0.015 250.0);
  --surface: oklch(0.985 0.008 250.0);
  --surface-2: oklch(0.915 0.020 250.0);
  --fg: oklch(0.230 0.020 260.0);
  --fg-muted: oklch(0.480 0.025 255.0);
  --accent: oklch(0.500 0.120 245.0);
  --accent-2: oklch(0.560 0.140 125.0);
  --line: oklch(0.860 0.015 250.0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-steam-dna.alt-mode ::selection { background: oklch(0.500 0.120 245.0); color: oklch(0.985 0.008 250.0); }
.theme-steam-dna.alt-mode a:hover { color: oklch(0.350 0.110 245.0); }
.theme-steam-dna.alt-mode input, .theme-steam-dna.alt-mode select, .theme-steam-dna.alt-mode textarea { background: oklch(1 0 0); box-shadow: inset 0 1px 2px oklch(0 0 0 / 10%); }
.theme-steam-dna.alt-mode kbd { background: oklch(0.94 0.01 250); border-color: oklch(0.80 0.02 250); color: var(--fg); box-shadow: inset 0 -2px 0 oklch(0 0 0 / 12%); }
.theme-steam-dna.alt-mode ::-webkit-scrollbar-track { background: oklch(0.90 0.015 250); }
.theme-steam-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.62 0.04 250); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
